# Build the solution grid based on pattern rule

test_input = [
    [0, 5, 0, 0, 0, 0, 0, 5, 0, 0, 5, 0],
    [0, 5, 0, 0, 0, 5, 5, 5, 0, 5, 5, 0],
    [5, 5, 5, 0, 0, 5, 0, 5, 5, 5, 8, 8],
    [0, 0, 5, 5, 5, 5, 0, 5, 0, 5, 5, 8],
    [0, 0, 0, 5, 0, 0, 0, 5, 0, 0, 5, 8],
]

R = 5
C = 12

# Find pattern cells
pattern_cells = []
for r in range(R):
    for c in range(C):
        if test_input[r][c] == 0 and r + 1 < R and c - 2 >= 0:
            if test_input[r + 1][c - 2] == 5:
                pattern_cells.append((r, c))

# Find components
def find_components(grid):
    Rg, Cg = len(grid), len(grid[0])
    visited = set()
    components = []
    for r in range(Rg):
        for c in range(Cg):
            if grid[r][c] == 0 and (r, c) not in visited:
                comp = set()
                visited.add((r, c))
                comp.add((r, c))
                stack = [(r, c)]
                while stack:
                    pr, pc = stack.pop()
                    for ddr in [-1, 0, 1]:
                        for dcc in [-1, 0, 1]:
                            if ddr == 0 and dcc == 0:
                                continue
                            nr, nc = pr + ddr, pc + dcc
                            if 0 <= nr < Rg and 0 <= nc < Cg and grid[nr][nc] == 0 and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                comp.add((nr, nc))
                                stack.append((nr, nc))
                components.append(sorted(comp))
    return components

test_components = find_components(test_input)
pattern_set = set(pattern_cells)

# Create solution
solution = [row[:] for row in test_input]
for comp in test_components:
    comp_set = set(comp)
    if comp_set & pattern_set:
        for r, c in comp:
            solution[r][c] = 8

print("Solution grid (only pattern->8, rest stay 0):")
for row in solution:
    print(' '.join(str(x) for x in row))

# Also try adding "7" cells - looking for right-edge touching components without pattern
for comp in test_components:
